        "JSONSchema": "{{{\n        \"title\": \"A registration form\",\n        \"description\": \"A simple form example.\",\n        \"type\": \"object\",\n        \"required\": [\n          \"firstName\",\n          \"lastName\"\n        ],\n        \"properties\": {\n          \"firstName\": {\n            \"type\": \"string\",\n            \"title\": \"First name\",\n            \"default\": \"Chuck\"\n          },\n          \"lastName\": {\n            \"type\": \"string\",\n            \"title\": \"Last name\"\n          },\n          \"age\": {\n            \"type\": \"integer\",\n            \"title\": \"Age\"\n          },\n          \"bio\": {\n            \"type\": \"string\",\n            \"title\": \"Bio\"\n          },\n          \"password\": {\n            \"type\": \"string\",\n            \"title\": \"Password\",\n            \"minLength\": 3\n          },\n          \"telephone\": {\n            \"type\": \"string\",\n            \"title\": \"Telephone\",\n            \"minLength\": 10\n          }\n        }\n      }}}",
        "UISchema": "{{{\n        \"firstName\": {\n          \"ui:autofocus\": true,\n          \"ui:emptyValue\": \"\",\n          \"ui:placeholder\": \"ui:emptyValue causes this field to always be valid despite being required\",\n          \"ui:autocomplete\": \"family-name\",\n          \"ui:enableMarkdownInDescription\": true,\n        },\n        \"lastName\": {\n          \"ui:autocomplete\": \"given-name\",\n          \"ui:enableMarkdownInDescription\": true,\n        },\n        \"age\": {\n          \"ui:widget\": \"updown\",\n          \"ui:title\": \"Age of person\",\n          \"ui:description\": \"(earth year)\"\n        },\n        \"bio\": {\n          \"ui:widget\": \"textarea\"\n        },\n        \"password\": {\n          \"ui:widget\": \"password\",\n          \"ui:help\": \"Hint: Make it strong!\"\n        },\n        \"telephone\": {\n          \"ui:options\": {\n            \"inputType\": \"tel\"\n          }\n        }\n      }}}",
        "formData": "{{{\n        \"firstName\": \"Chuck\",\n        \"lastName\": \"Norris\",\n        \"age\": 75,\n        \"bio\": \"Roundhouse kicking asses since 1940\",\n        \"password\": \"noneed\",\n        \"telephone\": \"1-800-KICKASS\"\n      }}}",
